#[derive(Debug, Clone, PartialEq, Default, serde::Serialize, serde::Deserialize)]
pub struct RaizAgentTurnPolicy {
    /// Output tokens per model call, reasoning included. Default 4096.
    #[serde(rename = "maxOutputTokens", default, skip_serializing_if = "Option::is_none")]
    pub max_output_tokens: Option<i64>,
    /// Model calls one reply may make: tool rounds plus the answer. The last call never offers tools, so the contact always gets an answer. Default 16.
    #[serde(rename = "maxSteps", default, skip_serializing_if = "Option::is_none")]
    pub max_steps: Option<i64>,
    /// Integration tool calls that change data (`effect: write`) one model step may run. A further one is refused with a fixed reason, and the Agent runs it in its next step after reading the first result. 0 forbids writes. Default 1.
    #[serde(rename = "maxWritesPerStep", default, skip_serializing_if = "Option::is_none")]
    pub max_writes_per_step: Option<i64>,
    /// Identical reads (same tool, same arguments) one reply may run; the next is refused with a fixed reason. Omitted: no limit, as an Agent that polls a pending operation repeats one read on purpose.
    #[serde(rename = "repeatedReadLimit", default, skip_serializing_if = "Option::is_none")]
    pub repeated_read_limit: Option<i64>,
    /// Per-tool rules, by the name the model sees.
    #[serde(rename = "tools", default, skip_serializing_if = "Option::is_none")]
    pub tools: Option<std::collections::BTreeMap<String, serde_json::Value>>,
}

